var VW = 1640, VH = 600;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, VW, VH);

var SERIF = "'Latin Modern Roman','Computer Modern',Georgia,'Times New Roman',Times,serif";
var C_ORANGE = '#c96f4e', C_ORANGE_ST = '#3b2a20';
var C_GREY = '#b6b6b6', C_GREY_ST = '#2f2f2f';
var C_TEAL = '#8ed0c4', C_BLUE = '#8fa9c2';
var C_ACCENT = '#e07b2f', C_WARN = '#992020';
var INK = '#111';

var arrowMk = draw.marker(12, 12, function (add) { add.path('M0,1 L12,6 L0,11 Z').fill(INK); });
arrowMk.ref(11.5, 6).attr('markerUnits', 'userSpaceOnUse');

function T(str, x, y, size, anchor, color) {
  var t = draw.plain(str).font({ family: SERIF, size: size || 20 });
  t.attr({ x: x, y: y, 'text-anchor': anchor || 'middle', 'dominant-baseline': 'middle', fill: color || INK });
  return t;
}
function VT(str, x, y, size, color) {
  var t = draw.plain(str).font({ family: SERIF, size: size || 15 });
  t.attr({ x: 0, y: 0, 'text-anchor': 'end', 'dominant-baseline': 'middle', fill: color || INK });
  t.attr('transform', 'translate(' + x + ',' + y + ') rotate(-90)');
  return t;
}
function aLine(x1, y1, x2, y2, w, col) {
  var l = draw.line(x1, y1, x2, y2).stroke({ color: col || INK, width: w || 1.8, linecap: 'butt' });
  l.marker('end', arrowMk);
  return l;
}
function pLine(x1, y1, x2, y2, w, col) {
  return draw.line(x1, y1, x2, y2).stroke({ color: col || INK, width: w || 1.8, linecap: 'butt' });
}
function inter(el, tip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () { showPopup(title, body); });
}

/* ── geometry ─────────────────────────────────────────────── */
var rowY = [118, 175, 232, 289, 346, 403, 460];
var tokens = ['<start>', 'It', 'takes', 'great', 'courage', 'to', 'let'];
var targets = ['It', 'takes', 'great', 'courage', 'to', 'let', 'yourself'];

var GB = { x: 392, y: 82, w: 566, h: 424 };
var OR = { x: 428, y: 104, w: 155, h: 372 };
var xL = 434, xR = 577;

/* ── headings ─────────────────────────────────────────────── */
T('Word', 227, 24, 25); T('embeddings', 227, 52, 25);
T('Transformer with', 673, 24, 25); T('masked attention', 673, 52, 25);
T('Linear +', 1207, 24, 25); T('softmax', 1207, 52, 25);
T('Probability of', 1420, 24, 25); T('target token', 1420, 52, 25);

/* ── layer ghosts (behind grey block) ─────────────────────── */
var ghostG = draw.group();

/* ── grey decoder block ───────────────────────────────────── */
var greyRect = draw.rect(GB.w, GB.h).move(GB.x, GB.y).radius(16)
  .fill(C_GREY).stroke({ color: C_GREY_ST, width: 2.6, dasharray: '11,7' });
inter(greyRect, 'One decoder layer',
  'Decoder layer',
  'Everything inside the grey box is a single decoder layer: masked self-attention, a residual add, a normalisation step, a position-wise feed-forward network, a second residual add and a second normalisation. Its input and output shapes are identical, which is why it can be stacked K times.');

/* ── masked self-attention block + fan ────────────────────── */
var orangeRect = draw.rect(OR.w, OR.h).move(OR.x, OR.y).radius(3)
  .fill(C_ORANGE).stroke({ color: C_ORANGE_ST, width: 2 });
inter(orangeRect, 'Masked self-attention',
  'Masked self-attention',
  'Each position builds a query and compares it with the keys of the positions it is allowed to see. The causal mask sets the scores of all future positions to −∞, so the fan of connections is lower-triangular: position i mixes information only from positions 0…i.');

var fanG = draw.group();
var fanLines = [];
var masked = true, K = 1, trace = 'idle', emphasis = null;

function renderFan() {
  fanG.clear(); fanLines = [];
  for (var i = 0; i < 7; i++) {
    for (var j = 0; j < 7; j++) {
      if (masked && j > i) continue;
      var fut = j > i;
      var l = fanG.line(xL, rowY[j], xR, rowY[i])
        .stroke({ color: fut ? '#8f1d1d' : '#2b1710', width: fut ? 1.3 : 1.1 });
      fanLines.push({ el: l, i: i, j: j, future: fut });
    }
  }
}

/* ── residual + plus nodes ────────────────────────────────── */
function plusNode(cx, cy) {
  var g = draw.group();
  var c = g.circle(22).center(cx, cy).fill('#fff').stroke({ color: INK, width: 2.2 });
  var a = g.line(cx - 7, cy, cx + 7, cy).stroke({ color: INK, width: 2.2 });
  var b = g.line(cx, cy - 7, cx, cy + 7).stroke({ color: INK, width: 2.2 });
  return {
    g: g, setColor: function (col) {
      c.stroke({ color: col }); a.stroke({ color: col }); b.stroke({ color: col });
    }
  };
}
function makeResidual(pts, cx, cy) {
  var poly = draw.polyline(pts).fill('none').stroke({ color: INK, width: 2 });
  poly.marker('end', arrowMk);
  var p = plusNode(cx, cy);
  var o = {
    poly: poly, plus: p,
    setColor: function (col) { poly.stroke({ color: col }); p.setColor(col); }
  };
  inter(poly, 'Residual (skip) connection', 'Residual connection',
    'The block input is carried around the sublayer and added back at the ⊕ node. This keeps the original token signal intact and gives gradients a short path, which is what makes deep stacks trainable.');
  inter(p.g, 'Residual addition ⊕', 'Residual addition ⊕',
    'The sublayer output is added element-wise to the sublayer input: out = x + Sublayer(x). Nothing is thrown away — the sublayer only writes a correction onto the running representation.');
  return o;
}

/* ── main path pieces inside the block ────────────────────── */
pLine(326, 289, 420, 289, 2.6);
aLine(326, 289, 424, 289, 2.6);
var res1 = makeResidual([[410, 289], [410, 94], [612, 94], [612, 276]], 612, 289);
aLine(583, 289, 599, 289, 2);

var tealBar1 = draw.rect(18, OR.h).move(648, OR.y).radius(9).fill(C_TEAL).stroke({ color: '#1d1d1d', width: 1.5 });
aLine(623, 289, 646, 289, 2);
inter(tealBar1, 'LayerNorm — features after attention', 'Normalisation / feature vectors',
  'After the residual add, each position\'s vector is normalised. The teal bar is the stack of seven feature vectors leaving the attention sublayer — one per input position, same length as before.');

/* feed-forward column */
pLine(666, 289, 690, 289, 2);
pLine(690, rowY[0], 690, rowY[6], 1.8);
var ffnCaps = [];
for (var i = 0; i < 7; i++) {
  aLine(690, rowY[i], 750, rowY[i], 1.6);
  var cap = draw.rect(54, 20).move(752, rowY[i] - 10).radius(10).fill(C_BLUE).stroke({ color: '#1d1d1d', width: 1.4 });
  ffnCaps.push(cap);
  pLine(806, rowY[i], 828, rowY[i], 1.6);
  inter(cap, 'Feed-forward network (position ' + (i + 1) + ')', 'Position-wise feed-forward network',
    'The same small two-layer MLP is applied independently to every position. It does no mixing across positions — all cross-token communication happens in the attention block — it just re-processes each vector on its own.');
}
pLine(828, rowY[0], 828, rowY[6], 1.8);
aLine(828, 289, 855, 289, 2);

var res2 = makeResidual([[678, 289], [678, 102], [868, 102], [868, 276]], 868, 289);
var tealBar2 = draw.rect(18, OR.h).move(900, OR.y).radius(9).fill(C_TEAL).stroke({ color: '#1d1d1d', width: 1.5 });
aLine(879, 289, 898, 289, 2);
inter(tealBar2, 'LayerNorm — output of the layer', 'Layer output vectors',
  'The second teal bar holds the seven output vectors of this decoder layer. They have exactly the same shape as the layer input, so the whole block can be applied again — that is what "×K" means.');

/* ── ×K annotation and ellipsis ───────────────────────────── */
aLine(918, 289, 988, 289, 2.4);
var dots = draw.group();
[1002, 1022, 1042].forEach(function (x) { dots.circle(8).center(x, 289).fill(INK); });
var kLabel = T('(×K)', 1022, 250, 25);
pLine(1054, 289, 1108, 289, 2.4);
inter(kLabel, 'K stacked identical layers', 'Stacking K layers',
  'The same decoder layer is repeated K times. Depth adds representational power but changes nothing about the interface: seven vectors in, seven vectors out, and every layer uses the same causal mask.');

/* ── embeddings ───────────────────────────────────────────── */
var embedDash = draw.rect(150, 386).move(152, 98).radius(14)
  .fill('none').stroke({ color: '#2f2f2f', width: 2.4, dasharray: '11,7' });
inter(embedDash, 'Word embeddings', 'Word embeddings',
  'Each token is looked up in an embedding table (plus a positional encoding) and becomes a row vector of real numbers. The seven empty cells in a row stand for the components of one embedding vector.');

var tokenLabels = [], tokenArrows = [], embedCells = [];
for (var i = 0; i < 7; i++) {
  tokenLabels.push(T(tokens[i], 118, rowY[i], 21, 'end'));
  tokenArrows.push(aLine(126, rowY[i], 160, rowY[i], 1.6));
  var cells = [];
  for (var c = 0; c < 6; c++) {
    cells.push(draw.rect(20, 26).move(164 + c * 20, rowY[i] - 13).fill('#fff').stroke({ color: INK, width: 1.3 }));
  }
  embedCells.push(cells);
  pLine(302, rowY[i], 326, rowY[i], 1.6);
}
pLine(326, rowY[0], 326, rowY[6], 2);

/* ── linear + softmax column ──────────────────────────────── */
pLine(1108, rowY[0], 1108, rowY[6], 2);
var linCaps = [];
for (var i = 0; i < 7; i++) {
  aLine(1108, rowY[i], 1144, rowY[i], 1.8);
  var lc = draw.rect(118, 36).move(1148, rowY[i] - 18).radius(18).fill(C_TEAL).stroke({ color: '#1d1d1d', width: 1.6 });
  linCaps.push(lc);
  inter(lc, 'Linear + softmax (position ' + (i + 1) + ')', 'Linear + softmax head',
    'One shared weight matrix projects the output vector of this position onto a score for every word in the vocabulary; softmax turns those scores into a probability distribution. The same head is reused at all seven positions.');
}

/* ── probability rows ─────────────────────────────────────── */
var probCells = [], probDeco = [], targetLabels = [];
var cxs = [1300, 1327, 1354, 1451, 1478];
for (var i = 0; i < 7; i++) {
  aLine(1266, rowY[i], 1296, rowY[i], 1.8);
  var cells = [];
  for (var k = 0; k < cxs.length; k++) {
    cells.push(draw.rect(27, 27).move(cxs[k], rowY[i] - 13.5).fill(C_BLUE).stroke({ color: '#1d1d1d', width: 1.2 }));
  }
  probCells.push(cells);
  var dg = draw.group();
  dg.line(1381, rowY[i] - 13.5, 1451, rowY[i] - 13.5).stroke({ color: '#1d1d1d', width: 1.2, dasharray: '2,4' });
  dg.line(1381, rowY[i] + 13.5, 1451, rowY[i] + 13.5).stroke({ color: '#1d1d1d', width: 1.2, dasharray: '2,4' });
  dg.plain('. . .').font({ family: SERIF, size: 17 })
    .attr({ x: 1416, y: rowY[i] - 3, 'text-anchor': 'middle', 'dominant-baseline': 'middle', fill: INK });
  probDeco.push(dg);
  targetLabels.push(T(targets[i], 1516, rowY[i], 21, 'start'));
  (function (row) {
    var hit = draw.rect(215, 32).move(1296, rowY[row] - 16).fill('#fff').opacity(0);
    inter(hit, 'P(next token) at position ' + (row + 1) + ' → “' + targets[row] + '”',
      'Probability of the target token',
      'This row is one probability distribution over the entire vocabulary. During training the loss pushes the mass onto the correct next token — “' + targets[row] + '” here — which is the input sequence shifted one step to the left.');
  })(i);
}

/* vocabulary axis labels */
var vocab = ['a', 'aardvark', 'abacus', 'zeta', 'zero'];
for (var k = 0; k < cxs.length; k++) VT(vocab[k], cxs[k] + 13.5, 480, 15);
T('. . .', 1416, 496, 17);

/* warning note (unmasked mode) */
var warnText = T('future tokens visible — prediction is trivial', 673, 574, 20, 'middle', C_WARN);
warnText.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
warnText.opacity(0);

/* ── layer ghosts renderer ────────────────────────────────── */
function renderLayers() {
  ghostG.clear();
  for (var k = K - 1; k >= 1; k--) {
    ghostG.rect(GB.w, GB.h).move(GB.x + k * 10, GB.y + k * 9).radius(16)
      .fill('#c7c7c7').opacity(0.95)
      .stroke({ color: '#5a5a5a', width: 2, dasharray: '9,6' });
  }
  kLabel.clear();
  kLabel.plain(K === 1 ? '(×K)' : '(×' + K + ')');
  kLabel.attr({ x: 1022, y: 250, 'text-anchor': 'middle', 'dominant-baseline': 'middle', fill: INK });
}

/* ── styling / trace ──────────────────────────────────────── */
function resetStyles() {
  for (var i = 0; i < 7; i++) {
    tokenLabels[i].attr({ fill: INK }).opacity(1);
    tokenArrows[i].opacity(1);
    embedCells[i].forEach(function (c) { c.fill('#fff').stroke({ color: INK, width: 1.3 }).opacity(1); });
    ffnCaps[i].stroke({ color: '#1d1d1d', width: 1.4 }).opacity(1);
    linCaps[i].stroke({ color: '#1d1d1d', width: 1.6 }).opacity(1);
    probCells[i].forEach(function (c) { c.fill(C_BLUE).stroke({ color: '#1d1d1d', width: 1.2 }).opacity(1); });
    probDeco[i].opacity(1);
    targetLabels[i].attr({ fill: INK }).opacity(1);
  }
  fanLines.forEach(function (f) {
    f.el.stroke({ color: f.future ? '#8f1d1d' : '#2b1710', width: f.future ? 1.3 : 1.1 }).opacity(1);
  });
  res1.setColor(INK); res2.setColor(INK);
  tealBar1.stroke({ color: '#1d1d1d', width: 1.5 });
  tealBar2.stroke({ color: '#1d1d1d', width: 1.5 });
}

var traceOrder = ['idle', 'prefix', 'maskedAttention', 'residualAdd', 'linearSoftmax', 'yourself'];

function applyVisuals() {
  resetStyles();
  warnText.opacity(masked ? 0 : 1);

  if (emphasis === 'shift') {
    for (var i = 0; i < 7; i++) {
      linCaps[i].stroke({ color: C_ACCENT, width: 3 });
      probCells[i].forEach(function (c) { c.stroke({ color: C_ACCENT, width: 2 }); });
      targetLabels[i].attr({ fill: '#b4571a' });
    }
  }

  var lvl = traceOrder.indexOf(trace);
  if (lvl < 1) return;

  if (lvl >= 1) {
    for (var i = 0; i < 7; i++) {
      embedCells[i].forEach(function (c) { c.stroke({ color: C_ACCENT, width: 2.3 }); });
      tokenLabels[i].attr({ fill: '#b4571a' });
    }
  }
  if (lvl >= 2) {
    fanLines.forEach(function (f) {
      if (f.i === 6) { f.el.stroke({ color: C_ACCENT, width: 2.2 }).opacity(1); }
      else { f.el.opacity(0.13); }
    });
  }
  if (lvl >= 3) {
    res1.setColor(C_ACCENT); res2.setColor(C_ACCENT);
    tealBar1.stroke({ color: C_ACCENT, width: 2.6 });
    tealBar2.stroke({ color: C_ACCENT, width: 2.6 });
    for (var i = 0; i < 7; i++) { if (i !== 6) ffnCaps[i].opacity(0.45); }
    ffnCaps[6].stroke({ color: C_ACCENT, width: 2.4 });
  }
  if (lvl >= 4) {
    for (var i = 0; i < 6; i++) linCaps[i].opacity(0.35);
    linCaps[6].stroke({ color: C_ACCENT, width: 3.2 }).opacity(1);
  }
  if (lvl >= 5) {
    for (var i = 0; i < 6; i++) {
      probCells[i].forEach(function (c) { c.opacity(0.28); });
      probDeco[i].opacity(0.28);
      targetLabels[i].opacity(0.3);
    }
    probCells[6].forEach(function (c) { c.fill('#cfd9e4').stroke({ color: C_ACCENT, width: 2 }).opacity(1); });
    probCells[6][3].fill(C_ACCENT);
    targetLabels[6].attr({ fill: '#b4571a' }).opacity(1);
  }
}

/* ── interaction handlers ─────────────────────────────────── */
function update_numLayers(v) { K = v; renderLayers(); }
function toggle_maskMode(on) { masked = !on; renderFan(); applyVisuals(); }
function update_predictTrace(s) { trace = s; applyVisuals(); }

/* ── demo steps ───────────────────────────────────────────── */
var steps = [
  {
    title: 'One layer, one pipeline',
    narration: 'Seven tokens enter as embedding vectors, pass through a single decoder layer, and each position leaves with its own output vector. Notice the sequence length never changes — one vector in, one vector out per position.',
    state: { numLayers: 1, maskMode: 'Causal (masked)', predictTrace: 'idle' }, emphasis: null
  },
  {
    title: 'Every position predicts at once',
    narration: 'Each output vector goes through the same Linear + softmax head to give a probability distribution over the whole vocabulary. The targets are the inputs shifted by one: “It” is predicted at the <start> position, “yourself” at the “let” position.',
    state: { numLayers: 1, maskMode: 'Causal (masked)', predictTrace: 'idle' }, emphasis: 'shift'
  },
  {
    title: 'Why the triangle',
    narration: 'Switch the mask off and the attention fan becomes full: each position can now see future tokens, so the “let” position could simply copy “yourself” from its neighbour. Switch back and only backward-looking connections remain.',
    state: { numLayers: 1, maskMode: 'Unmasked (bidirectional)', predictTrace: 'idle' }, emphasis: null
  },
  {
    title: 'Trace one prediction',
    narration: 'With the causal mask restored, follow the prefix <start> It takes great courage to let through its allowed attention lines, the two residual additions, and the softmax that concentrates probability on “yourself”.',
    state: { numLayers: 1, maskMode: 'Causal (masked)', predictTrace: 'yourself' }, emphasis: null
  },
  {
    title: 'Stack it K times',
    narration: 'Expanding ×K reveals identical layers chained together — same mask, same shapes, more mixing. Depth adds representational power without changing the input/output interface of the block.',
    state: { numLayers: 5, maskMode: 'Causal (masked)', predictTrace: 'idle' }, emphasis: null
  }
];
var stepIdx = 0;

function applyStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  var s = steps[stepIdx];
  var nl = s.state.numLayers;
  document.getElementById('numLayersInput').value = nl;
  document.getElementById('numLayersVal').value = nl;
  K = nl; renderLayers();

  var unm = (s.state.maskMode === 'Unmasked (bidirectional)');
  document.getElementById('maskModeInput').checked = unm;
  masked = !unm; renderFan();

  document.getElementById('predictTraceInput').value = s.state.predictTrace;
  trace = s.state.predictTrace;
  emphasis = s.emphasis || null;
  applyVisuals();

  document.getElementById('demoTitle').textContent = s.title;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + ' / ' + steps.length;
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

/* ── boot ─────────────────────────────────────────────────── */
renderFan();
renderLayers();
applyStep(0);
window.__markRendered();
